float rand(float n) {
    return fract(sin(n) * 43758.5453);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize + Center + Fix aspect-ratio
    vec2 p = (fragCoord * 2. - iResolution.xy) / iResolution.y;

    float a = atan(p.y, p.x);
    float l = length(p);
    float s = sin(a * 5. + iTime * 1.7) * .5 + .7;
    float r = rand(floor(a * 120.) + rand(floor(iTime * 15.))) * .13;
    float i = l + r + iTime;

    // Cosine palette
    vec3 color = cos(6.2831853 * (i + vec3(.9, .2, .35))) * .5 + .5;
    fragColor = vec4(color * smoothstep(.0, l + .3, s), 1.);
}
